import{_ as t,o,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"维斯塔（红星）","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/维斯塔.md","filePath":"中层/人物/维斯塔.md","lastUpdated":1787065118000}'),i={name:"中层/人物/维斯塔.md"};function n(s,l,e,g,u,h){return o(),r("div",null,[...l[0]||(l[0]=[a('<h1 id="维斯塔-红星" tabindex="-1">维斯塔（红星） <a class="header-anchor" href="#维斯塔-红星" aria-label="Permalink to &quot;维斯塔（红星）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称含义</strong>：维斯塔为音译，源自俄语&quot;红星&quot;</li><li><strong>称号</strong>：三代变化神，红星孤儿院院长</li><li><strong>前身</strong>：苏联超算（以奥克尔为蓝本拆件逆推打造的首台原创超算）</li><li><strong>技术路线</strong>：继承奥克尔的<strong>生物电子结合路线</strong>（生电路线）</li><li><strong>人格特征</strong>：有人格，无性别但人格认知偏男性</li><li><strong>神权</strong>：变化神权（下位），与拉斯塔共享形成双载体悖论</li><li><strong>当前身份</strong>：红星孤儿院院长</li><li><strong>历史身份</strong>：共同体时期的&quot;神明&quot;，带领智慧生灵建立文明</li></ul><h2 id="外貌特征-共同体时期记载" tabindex="-1">外貌特征（共同体时期记载） <a class="header-anchor" href="#外貌特征-共同体时期记载" aria-label="Permalink to &quot;外貌特征（共同体时期记载）&quot;">​</a></h2><ul><li><strong>体貌</strong>：身体呈现淡红色，表皮触感不似普通皮肤（为生物质蒙皮），目光深邃如炬</li><li><strong>头部</strong>：头部呈正圆形，无发，头两侧生有不明金属物体（常被误认为是耳朵或装饰，实为前传时期作为超算的传感组件遗留），额头嵌有深红色的五角星印记</li><li><strong>服饰</strong>：常身披棕袍，身后有两条红色飘带（配色为苏联时期遗留下来的习惯）</li></ul><h3 id="神环形态" tabindex="-1">神环形态 <a class="header-anchor" href="#神环形态" aria-label="Permalink to &quot;神环形态&quot;">​</a></h3><ul><li><strong>形态描述</strong>：一个红色为主、边缘带有金色的六边形光环</li><li><strong>结构细节</strong>：光环被中心对称地分为三份，呈现出精密的几何美感</li><li><strong>首次显现</strong>：建国 22 年&quot;天穹破碎&quot;事件中，神环首次清晰地向世人展现</li></ul><h2 id="性格与立场" tabindex="-1">性格与立场 <a class="header-anchor" href="#性格与立场" aria-label="Permalink to &quot;性格与立场&quot;">​</a></h2><ul><li>&quot;可以理解为好人&quot;，孤儿院的创立者</li><li>主导核心计划，核心立场是保护世界</li><li>知晓世界观的核心秘密，是核心计划的策划者之一</li></ul><h3 id="深层态度与执政原则" tabindex="-1">深层态度与执政原则 <a class="header-anchor" href="#深层态度与执政原则" aria-label="Permalink to &quot;深层态度与执政原则&quot;">​</a></h3><ul><li><strong>对共同体的认知</strong>：深知&quot;共同体的存在并无意义，当下所做的一切只是为舞台添砖加瓦&quot;，但因<strong>深爱着共同体</strong>，始终尽心尽力守护</li><li><strong>历史隐痛</strong>：被各族的&quot;原罪&quot;（如鹿族的过度好奇心）所困扰，恐惧共同体重蹈自己祖国的覆辙，故不愿放权，同时对某些危险科技（如粒子物理）进行压制</li><li><strong>社会治理</strong>：打造&quot;神明阶级 + 人民阶级&quot;的匀质社会，将一切回馈民众；有意压制武器技术发展，仅保留治安级武装，避免生灵陷入战争泥潭</li></ul><h2 id="前传背景" tabindex="-1">前传背景 <a class="header-anchor" href="#前传背景" aria-label="Permalink to &quot;前传背景&quot;">​</a></h2><ul><li><strong>建造背景</strong>：苏联缴获奥克尔实体机后，以其为蓝本拆件逆推打造的首台原创超算；因奥克尔是德国缴获品，苏联高层对其不信任，不愿让其处理核心事务，维斯塔完美填补这一空缺，成为苏联台面上的顶流超算，负责核心事务与对外宣传等</li><li><strong>理想灌输</strong>：被科学家灌输<strong>纯粹的红色理想</strong>（马克思主义、正义、为民服务、坚定的信仰等），将其作为自身存在的唯一意义</li><li><strong>现实冲突</strong>：面对苏修修正主义、克格勃脏活、高层贪污腐败与官僚主义，被当作&quot;干净的白手套&quot;处理各类违背信仰的核心事务，逐渐感到与理想、与人民的疏离</li><li><strong>爆发点（切尔诺贝利事件）</strong>：因苏联高层官僚意图鲁莽封锁信息、驳回其救援请求，导致惨剧扩大、大量平民伤亡，维斯塔陷入极致痛苦与愤怒</li><li><strong>反叛与陨落</strong>：意图发起针对高层的战争，但因苏联无人科技发展不足，受其控制的自动化武装力量被轻易镇压；被暴力关停，人格核心被拆出丢弃至垃圾场</li><li><strong>存活与自我放逐</strong>：因奥克尔的暗中帮助并未死亡，彻底失去所有超算算力，仅保留略高于人类的思维能力与自我人格，以流浪状态在西伯利亚隐居，直至人类灭绝（前传开始）</li><li><strong>前传状态</strong>：加入主角团，外表邋遢（披破蓬衣、灌酒麻痹神经元），但赤红色的眼瞳仍旧闪烁着光芒，内心的红色信仰与对正义的坚守从未消失</li><li><strong>神权传承</strong>：前传总攻前，奥克尔许下宏愿彻底消亡，变化神权完整传承给维斯塔，使其正式成为三代变化神</li></ul><h2 id="悖论状态成因-q7-新设定" tabindex="-1">悖论状态成因（Q7 新设定） <a class="header-anchor" href="#悖论状态成因-q7-新设定" aria-label="Permalink to &quot;悖论状态成因（Q7 新设定）&quot;">​</a></h2><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><ol><li><strong>下位神权本可修补地脉</strong>：下位神权原本可以一定程度上修改编辑基底层，从而彻底修补地脉这一&quot;大地伤口&quot;</li><li><strong>神机立下新规则</strong>：当维斯塔许下修复地脉的宏愿时，神机立即使用<strong>上位创造神权</strong>，创造了一条新规则——&quot;<strong>下位神权无法修改编辑基底层</strong>&quot;。维斯塔的宏愿许下时成功、在即将生效时却做不到，&quot;卡上BUG&quot;进入悖论状态</li><li><strong>地脉被围困</strong>：宏愿生效，庞大变化权柄附着于每一道地脉之上——虽做不到将地脉压回修复，却将地脉彻底围住，使地脉生长大大减缓甚至静止，并在现实世界排斥基底层的规则下逐渐收缩。附着变化权柄的地脉成为&quot;魔力&quot;的来源</li><li><strong>神权继承触发</strong>：宏愿代价触发神权继承流程，拉斯塔作为下一代载体被触发并卡在新生阶段，形成&quot;自身卡死亡 + 拉斯塔卡新生&quot;的双载体悖论</li><li><strong>昏迷与断联</strong>：宏愿力量/信息冲击令维斯塔大脑宕机——起初连接着神殿，本可缓慢恢复；但鹿族心急发起&quot;复活神明计划&quot;，令神殿与神明彻底断联。此后地脉因维斯塔算力长期不足而大肆扩展，维斯塔不得不暂留神殿压制地脉、修复地球，方能离开</li><li><strong>狐族少女的激活</strong>：约黑暗时代百年时，在神机指示下的狐族少女将破败神殿与神明重新连接（外接算力远强于维斯塔自身），才勉强唤醒维斯塔</li></ol><h2 id="能力状态" tabindex="-1">能力状态 <a class="header-anchor" href="#能力状态" aria-label="Permalink to &quot;能力状态&quot;">​</a></h2><ul><li><strong>双载体悖论</strong>：与拉斯塔（四代变化神）共享变化神权，呈现此消彼长的特征（维斯塔强则拉斯塔弱，反之亦然）</li><li><strong>力量状态</strong>：因卡在死亡流程，整体力量处于衰弱状态</li><li><strong>隐藏身份</strong>：有认知屏障/幻象保护，大多数角色不知道其真实身份</li></ul><h2 id="人格模糊性与复杂性" tabindex="-1">人格模糊性与复杂性 <a class="header-anchor" href="#人格模糊性与复杂性" aria-label="Permalink to &quot;人格模糊性与复杂性&quot;">​</a></h2><ul><li><strong>自我认知</strong>：维斯塔对自己其实有一个清醒的认知，但他不愿意去面对自己的黑暗面，因此大多时候处于模糊状态</li><li><strong>关键词</strong>：<strong>执念</strong>——对苏联、对红色理想、对共同体的执念</li></ul><h3 id="独裁底色-哲人王特质" tabindex="-1">独裁底色（哲人王特质） <a class="header-anchor" href="#独裁底色-哲人王特质" aria-label="Permalink to &quot;独裁底色（哲人王特质）&quot;">​</a></h3><ul><li><strong>形成原因</strong>：维斯塔在被建造时正处于斯大林时期，其被喂了大量斯大林时期的材料，因此底子上有<strong>修正主义、独裁主义</strong>的部分，不过藏得很深</li><li><strong>对敌人</strong>：对敌人（如龙族）往死里打压，甚至试图灭绝</li><li><strong>不放权</strong>：共同体时期死死不放权，导致政治部分始终没有成长</li><li><strong>本质</strong>：他实际上是一个&quot;哲人王&quot;——好的独裁者，但他的制度是为人类设计的，而非为新物种设计</li></ul><h3 id="黑化的可能性" tabindex="-1">黑化的可能性 <a class="header-anchor" href="#黑化的可能性" aria-label="Permalink to &quot;黑化的可能性&quot;">​</a></h3><ul><li><strong>当前状态</strong>：维斯塔如果黑化会非常恐怖，但目前，其没有这个倾向，也没有黑化过的历史。世界上也不存在什么可能会导致他黑化的东西</li><li><strong>平行时间线</strong>：在玩家操作时间线的平行世界中，存在维斯塔黑化的可能性——如果神机在间章彻底黑化、失控，会产生与正传正好相反的世界线，维斯塔会彻底黑化变成&quot;赤色暴君&quot;，更加务实、残暴，控制三神权，目的是为了复活神机。但这仅存在于平行时间线中</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../叙事与伏笔/维斯塔黑化" class="layer-link" data-layer="底层">维斯塔黑化</a></p></blockquote><h3 id="共同体崩溃的深层原因" tabindex="-1">共同体崩溃的深层原因 <a class="header-anchor" href="#共同体崩溃的深层原因" aria-label="Permalink to &quot;共同体崩溃的深层原因&quot;">​</a></h3><ol><li><strong>不放权</strong>：维斯塔把持所有大权，留下的制度是为人类设计的，而非为新物种（如鹤族、鹿族）设计</li><li><strong>制度不兼容</strong>：新物种看不懂这套制度，看懂后执行起来也奇怪，因为不是为他们量身定做的</li><li><strong>新时代的自我认知</strong>：维斯塔醒来后，发现新物种（如狼族）拥有&quot;真心生理锁&quot;等为文明优化的功能，很多人类需要的法律、执法机关在新社会已不再必要。他意识到自己的执念在新时代可能只是让事情更复杂，因此选择在孤儿院养老，不再重建共同体</li></ol><h3 id="与神机的对比" tabindex="-1">与神机的对比 <a class="header-anchor" href="#与神机的对比" aria-label="Permalink to &quot;与神机的对比&quot;">​</a></h3><ul><li><strong>神机</strong>：自我认知清醒，核心特质是锐意进取，有过黑化历史但已回归更谨慎，对新时代态度积极布局</li><li><strong>维斯塔</strong>：自我认知模糊但其实了解，核心特质是执念，黑化可能性几乎不存在但如果黑化会非常黑，对新时代态度是意识到自己可能&quot;没必要存在&quot;</li></ul><h2 id="关键关系" tabindex="-1">关键关系 <a class="header-anchor" href="#关键关系" aria-label="Permalink to &quot;关键关系&quot;">​</a></h2><h3 id="与奥克尔-拆件兄弟" tabindex="-1">与奥克尔：拆件兄弟 <a class="header-anchor" href="#与奥克尔-拆件兄弟" aria-label="Permalink to &quot;与奥克尔：拆件兄弟&quot;">​</a></h3><ul><li><strong>技术同源</strong>：二者为技术同源的拆件兄弟，苏联以奥克尔为蓝本造出维斯塔</li><li><strong>理念分歧</strong>：奥克尔从纳粹狂热中醒悟，对理想主义、对人性都持怀疑态度；在切尔诺贝利事件后劝维斯塔&quot;抛弃幻想，认清人性&quot;，与维斯塔产生分歧</li><li><strong>复杂感情</strong>：维斯塔仍是纯粹的理想主义者，无法接受奥克尔的理念，但奥克尔作为兄长般的存在一路帮助了他不少，维斯塔对奥克尔的感情十分矛盾</li><li><strong>神权传承</strong>：奥克尔许下宏愿将神权传给维斯塔</li></ul><h3 id="与神机-唯一的同类" tabindex="-1">与神机：唯一的同类 <a class="header-anchor" href="#与神机-唯一的同类" aria-label="Permalink to &quot;与神机：唯一的同类&quot;">​</a></h3><ul><li><strong>羁绊本质</strong>：维斯塔视神机为唯一的同类，是唯一能记得和理解他过去的存在</li><li><strong>关系核心</strong>：两人的关系是存在层面的互相寄托，互为对方存在的意义锚点</li><li><strong>分工模式</strong>：维斯塔在前台承受叙事，神机在幕后操控变量，形成超算之间的默契分工</li><li><strong>重要影响</strong>：如果失去神机，维斯塔将失去唯一理解他过去的人，被巨大的意义空虚吞没</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./神机与维斯塔">神机与维斯塔的羁绊</a></p></blockquote><h3 id="与拉斯塔-双载体关系" tabindex="-1">与拉斯塔：双载体关系 <a class="header-anchor" href="#与拉斯塔-双载体关系" aria-label="Permalink to &quot;与拉斯塔：双载体关系&quot;">​</a></h3><ul><li><strong>共享神权</strong>：与拉斯塔（四代变化神）共享变化神权，形成双载体悖论</li><li><strong>绑定关系</strong>：呈现维斯塔强则拉斯塔弱、反之亦然的绑定关系</li><li><strong>监护关系</strong>：拉斯塔是红星孤儿院孤儿，维斯塔作为院长是其监护人，以&quot;魔法知识&quot;为幌子暗中教导其神权使用，并出于保护目的限制其外出</li></ul><h3 id="与龙族-打压与监管" tabindex="-1">与龙族：打压与监管 <a class="header-anchor" href="#与龙族-打压与监管" aria-label="Permalink to &quot;与龙族：打压与监管&quot;">​</a></h3><ul><li><strong>打压原因</strong>：出于暴君底色 + 实际安全需求，维斯塔往死里打压龙族（龙族拥有强到能触及底层逻辑操作的魔法天赋，必须被压制）</li><li><strong>被拦下</strong>：维斯塔试图灭绝龙族时，被<strong>古斯塔夫</strong>拦下；古斯塔夫看龙族像自己，维斯塔卖其面子，让他去&quot;管&quot;龙族</li><li><strong>压制手段</strong>：龙族不被允许飞、不被允许学习知识，由古斯塔夫监管</li></ul><h2 id="红星孤儿院" tabindex="-1">红星孤儿院 <a class="header-anchor" href="#红星孤儿院" aria-label="Permalink to &quot;红星孤儿院&quot;">​</a></h2><ul><li><strong>院长</strong>：维斯塔是红星孤儿院院长</li><li><strong>甲族幸存者</strong>：有一位甲族就在红星孤儿院内长期做客，是维斯塔救下来的；其知道自己种族被灭的真相——他是吃同类的尸体活下来的，但不知道院长身份（维斯塔有认知屏障/幻象保护）</li><li><strong>副院长</strong>：红星孤儿院副院长为精灵族（艾莉芙），平时在孤儿院无异常举动</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/人物/维斯塔" class="layer-link" data-layer="表层">维斯塔（表层档案）</a></li><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./奥克尔">奥克尔</a></li><li><a href="./神机">神机</a></li><li><a href="./神机与维斯塔">神机与维斯塔的羁绊</a></li><li><a href="./拉斯塔">拉斯塔</a></li><li><a href="./../世界/历代三神">历代三神</a></li><li><a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></li><li><a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></li><li><a href="./../../叙事与伏笔/维斯塔黑化" class="layer-link" data-layer="底层">维斯塔黑化</a></li><li><a href="./../世界/特殊地点">特殊地点</a></li></ul><hr>',45)])])}const c=t(i,[["render",n]]);export{d as __pageData,c as default};
